   return DevicePolishReview.Active||AuditFixesReview.Active||PopupCloseReview.Active||Array.Exists(Environment.GetCommandLineArgs(),a=>a.EndsWith("-test")||a=="-crisp-ui-review"||a=="-device-polish-review"||a=="-settings-language-review"||a=="-language-pref-verify");
