  public void Build(PinPopGame owner){game=owner;testing=IsReviewSession();font=CrispUI.Bold;var canvas=new GameObject("Adventure interface",typeof(RectTransform),typeof(Canvas),typeof(GraphicRaycaster));canvas.layer=5;canvas.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceCamera;canvas.GetComponent<Canvas>().worldCamera=owner.Hud.UICamera;canvas.GetComponent<Canvas>().planeDistance=.8f;canvas.GetComponent<Canvas>().sortingOrder=40;var shade=CrispUI.Rect("Adventure fullscreen shade",canvas.transform,0,0,1,1);shade.anchorMin=Vector2.zero;shade.anchorMax=Vector2.one;shade.offsetMin=shade.offsetMax=Vector2.zero;modalShade=shade.gameObject.AddComponent<Image>();modalShade.color=new Color(.04f,.10f,.14f,.65f);modalShade.raycastTarget=true;modalShade.gameObject.SetActive(false);frame=Rect("Adventure frame",canvas.transform,0,0,600,1000);frame.anchorMin=frame.anchorMax=new Vector2(.5f,.5f);frame.pivot=new Vector2(.5f,.5f);
