  void Update(){if(frame==null||game.Adventure==null)return;var view=game.GetComponent<HtmlReferenceHUD>();var r=view.AppRect;frame.anchoredPosition=new Vector2(r.center.x-CrispUI.Width/2,r.center.y-CrispUI.Height/2);frame.localScale=Vector3.one*Mathf.Min(r.width/600,r.height/1000);
