   toolbar.SetActive(!view.CrispReady&&!game.InMenu&&!game.Finished&&clear&&!showing);homeButton.SetActive(false);pocket.gameObject.SetActive(!game.InMenu&&!game.Finished&&!showing&&clear&&game.Adventure.PocketColor>=0);
   stock.text="";for(int i=0;i<4;i++)if(lastStock[i]!=game.Adventure.Data.stock[i]){lastStock[i]=game.Adventure.Data.stock[i];counts[i].text="×"+lastStock[i];}float scale=Mathf.Min(frame.localScale.x,frame.localScale.y);if(Mathf.Abs(fontScale-scale)>.001f){fontScale=scale;ResizeFonts();}if(lastPocket!=game.Adventure.PocketColor){lastPocket=game.Adventure.PocketColor;pocket.text=lastPocket<0?"":GameLocalization.Format("CEP: {0} · iki eşini bekliyor",Art.Names[lastPocket]);}
   if(showing&&Input.GetKeyDown(KeyCode.Escape)){Dismiss();return;}
   if(!testing&&!game.InMenu&&!game.Transitioning&&!game.Busy&&!game.Finished&&clear&&!showing&&seenAttempt!=game.AttemptId){if(openedAt<=0)openedAt=Time.unscaledTime;if(Time.unscaledTime-openedAt>.7f){seenAttempt=game.AttemptId;openedAt=0;ShowNextLesson();}}
