  public void ShowNextLesson(){PresentLesson(game.Adventure.Lesson());}
  public void RefreshLanguage(){lastPocket=-2;}
  void PresentLesson(string text){if(string.IsNullOrEmpty(text))return;int split=text.IndexOf('\n');string title=split<0?text:text.Substring(0,split);Open(title,split<0?"":text.Substring(split+1));lesson=true;if(LessonDemo.Supports(title)){var demo=Rect("Mechanic demonstration",modal.transform,70,360,460,190).gameObject.AddComponent<LessonDemo>();demo.Build(title,game);FitLesson(490);return;}var color=Mathf.Max(0,PinPopLayouts.ColorCount(game.Level)-1);var icon=Image("Unlocked character",modal.transform,245,360,110,145,Color.white);icon.sprite=Resources.Load<Sprite>("PinIcons/pin-"+color);icon.preserveAspect=true;FitLesson(450);}
  void Open(string title,string body){if(showing)Close();game.CancelPull();Time.timeScale=0;showing=true;modal=Rect("Adventure modal",frame,0,0,600,1000).gameObject;var mr=modal.GetComponent<RectTransform>();mr.pivot=Vector2.one*.5f;mr.anchoredPosition=new Vector2(300,-500);modalShade.gameObject.SetActive(true);Image("Adventure card border",modal.transform,28,98,544,674,Art.Hex("C8BC97"));Image("Adventure card",modal.transform,30,100,540,670,Art.Hex("304F62"),true);Label(modal.transform,"Eyebrow",70,130,460,25,"PINPOP · LUNAPARK MACERASI",12,"D8C595").alignment=TextAnchor.MiddleCenter;Label(modal.transform,"Modal title",60,170,480,60,title,27,"FFF0C9").alignment=TextAnchor.MiddleCenter;var text=Label(modal.transform,"Modal explanation",65,240,470,100,body,17,"E7EEE7");text.font=CrispUI.Regular;text.fontStyle=FontStyle.Normal;text.alignment=TextAnchor.MiddleCenter;BuildCloseButton();StartCoroutine(Reveal(modal.transform));}
  void BuildCloseButton(){var hit=Rect("ADVENTURE_CLOSE",modal.transform,484,94,84,84);var touch=hit.gameObject.AddComponent<Image>();touch.color=Color.clear;var art=Image("Adventure close artwork",hit,16,18,52,48,Art.Hex("456C7F"));CrispUI.Icon("Adventure close cross",art.transform,14,12,24,24,CrispIcon.Kind.Close,Art.Hex("FFF3DC"));var button=hit.gameObject.AddComponent<UnityEngine.UI.Button>();button.targetGraphic=art;button.onClick.AddListener(Dismiss);hit.gameObject.AddComponent<HtmlButtonFeedback>().Artwork=art.rectTransform;}
  void FitLesson(float height){modal.transform.Find("Adventure card").GetComponent<RectTransform>().sizeDelta=new Vector2(540,height);modal.transform.Find("Adventure card border").GetComponent<RectTransform>().sizeDelta=new Vector2(544,height+4);float shift=500-(100+height/2);foreach(RectTransform child in modal.transform)child.anchoredPosition+=Vector2.down*shift;}
  void Dismiss(){bool next=lesson;Close();if(next)ShowNextLesson();}
  public void Close(){if(modalShade!=null)modalShade.gameObject.SetActive(false);if(modal!=null){foreach(var t in modal.GetComponentsInChildren<Text>(true))fontSizes.Remove(t);modal.SetActive(false);Destroy(modal);}modal=null;showing=false;lesson=false;if(!game.Finished)Time.timeScale=1;UnityEngine.EventSystems.EventSystem.current?.SetSelectedGameObject(null);}
  public void ShowMap(){if(PinPopSplash.Visible)return;if(game.Transitioning||game.RewardedVideo!=null&&game.RewardedVideo.Busy)return;DrawMap();}
  void DrawMap(float? offset=null,int? requestedFocus=null){int focus=requestedFocus??AdventureRules.ClampLevel(game.HighestLevel);if(!AdventureRules.CanVisitRegion(focus/AdventureRules.LevelsPerRegion,game.HighestLevel))return;Open("","");foreach(Transform child in modal.transform)if(child.name!="Modal shade")child.gameObject.SetActive(false);var map=modal.AddComponent<CarnivalMapView>();map.Build(game,focus,level=>{Close();game.Hud.PlayLevel(level);},checkpoint=>{float position=map.ScrollOffset;if(game.Adventure.ClaimChest(checkpoint)){DrawMap(position,focus);game.Hud.Toast(GameLocalization.Format("SANDIK AÇILDI · +{0} COIN",game.Adventure.LastChestCoins),2);}},Close,region=>DrawMap(null,AdventureRules.FocusForRegion(region,game.HighestLevel)));if(offset.HasValue)map.SetScrollOffset(offset.Value);}
  public void ShowBooster(int id){if(game.Busy||game.Finished||game.Transitioning||game.IsPulling)return;string[] descriptions={"Sıradaki topun rengini seç. Hamle harcamaz.\nMasada kalan renklerden birini seçebilirsin.","Bir sonraki top bütün renklere etki eder.\nDüşen dubalar kendi renkleriyle toplanır.","Bekleyen bir dubayı tek kişilik cebe taşı.\nAynı renkten iki duba gelince üçlü tamamlanır.","Mevcut masayı koruyarak üç hamle ekle.\nÖdüllü video hakkını tüketmez."};Open(GameLocalization.Text(AdventureRules.Boosters[id]).ToUpper(GameLocalization.Culture),GameLocalization.Format("{0}\nEnvanter: {1}",descriptions[id],game.Adventure.Data.stock[id]));
