   else if(id==2){int n=0;foreach(var item in game.MatchTray.Items){if(item.Matched||!item.Arrived)continue;int token=item.Id;var b=Button(modal.transform,"POCKET_CHOICE_"+token,70+(n%5)*94,370+(n/5)*100,84,84,"",()=>{Close();game.Adventure.Use(id,-1,token);},"466B7A");var icon=Image("Pocket figure",b.transform,12,3,60,76,Color.white);icon.sprite=Resources.Load<Sprite>("PinIcons/pin-"+item.Color);icon.preserveAspect=true;b.interactable=game.Adventure.PocketColor<0&&game.Adventure.Data.stock[id]>0;n++;}if(n==0||game.Adventure.PocketColor>=0)Label(modal.transform,"Pocket availability",65,410,470,70,n==0?"Önce tepsiye bir duba topla.":"Cep dolu; iki eşini toplayarak boşalt.",18,"F4E1B4").alignment=TextAnchor.MiddleCenter;}
   else Button(modal.transform,"BOOSTER_USE",140,400,320,65,"KULLAN",()=>{Close();game.Adventure.Use(id);},"70935E").interactable=game.Adventure.Data.stock[id]>0&&(id!=1||!game.Adventure.RainbowArmed);
   Button(modal.transform,"BOOSTER_BUY",110,610,380,65,GameLocalization.Format("+1 AL · {0} COIN",AdventureRules.Prices[id]),()=>{if(game.Adventure.Buy(id)){ShowBooster(id);game.Hud.Toast(GameLocalization.Format("Envantere +1 {0}",AdventureRules.Boosters[id]),2);}},"B08A43").interactable=game.Coins>=AdventureRules.Prices[id]&&game.Adventure.Data.stock[id]<999;Label(modal.transform,"Booster balance",110,690,380,40,GameLocalization.Format("BAKİYE: {0} COIN",game.Coins),16,"F4E1B4").alignment=TextAnchor.MiddleCenter;
  }
  IEnumerator Reveal(Transform target){if(game.ReducedMotion)yield break;for(float t=0;t<.18f;t+=Time.unscaledDeltaTime){if(target==null)yield break;float a=Mathf.Clamp01(t/.18f);target.localScale=Vector3.one*(.96f+.04f*(1-Mathf.Pow(1-a,3)));yield return null;}if(target!=null)target.localScale=Vector3.one;}
  RectTransform Rect(string name,Transform parent,float x,float y,float w,float h){var o=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer));o.layer=5;var r=o.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
