  Text Label(Transform parent,string name,float x,float y,float w,float h,string text,int size,string color){var t=Rect(name,parent,x,y,w,h).gameObject.AddComponent<CrispText>();t.font=font;t.fontSize=size;t.fontStyle=FontStyle.Bold;t.color=Art.Hex(color);t.text=text;t.alignment=TextAnchor.MiddleLeft;fontSizes[t]=size;t.fontSize=Mathf.Max(Mathf.Max(size,19),Mathf.CeilToInt(12/Mathf.Max(.1f,Mathf.Min(frame.localScale.x,frame.localScale.y))));t.raycastTarget=false;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;return t;}
  Button Button(Transform parent,string name,float x,float y,float w,float h,string text,UnityEngine.Events.UnityAction action,string color){var bg=CrispUI.Panel(name,parent,x,y,w,h,Art.Hex(color),10);bg.raycastTarget=true;var button=bg.gameObject.AddComponent<Button>();button.targetGraphic=bg;button.onClick.AddListener(action);button.gameObject.AddComponent<HtmlButtonFeedback>().Artwork=bg.rectTransform;Label(bg.transform,name+" label",4,2,w-8,h-4,text,16,"FFF3DC").alignment=TextAnchor.MiddleCenter;return button;}
  void ResizeFonts(){foreach(var pair in fontSizes)if(pair.Key!=null)pair.Key.fontSize=Mathf.Max(Mathf.Max(pair.Value,19),Mathf.CeilToInt(12/Mathf.Max(.1f,fontScale)));}
  static Sprite panel;static Sprite PanelSprite(){if(panel!=null)return panel;var t=new Texture2D(32,32,TextureFormat.RGBA32,false);var pixels=new Color32[1024];for(int y=0;y<32;y++)for(int x=0;x<32;x++){float dx=Mathf.Max(6-x,Mathf.Max(0,x-25)),dy=Mathf.Max(6-y,Mathf.Max(0,y-25));pixels[y*32+x]=dx*dx+dy*dy<=36?Color.white:Color.clear;}t.SetPixels32(pixels);t.Apply();panel=Sprite.Create(t,new Rect(0,0,32,32),Vector2.one*.5f,100,0,SpriteMeshType.FullRect,Vector4.one*8);return panel;}
